const rows = $input.all().map(item => item.json);

let headerRowIndex = -1;
let headerMap = null;
for (let i = 0; i < rows.length; i++) {
  const values = Object.values(rows[i]);
  if (values.includes('Customer Unique ID')) {
    headerRowIndex = i;
    headerMap = {};
    for (const [key, val] of Object.entries(rows[i])) {
      headerMap[key] = val;
    }
    break;
  }
}

if (headerRowIndex === -1) {
  throw new Error('No se encontro la fila de encabezados reales (buscando "Customer Unique ID") en el Excel de DealerCenter.');
}

function excelDateToISO(value) {
  if (value === '' || value === null || value === undefined) return '';
  if (typeof value === 'number') {
    const ms = Math.round((value - 25569) * 86400 * 1000);
    return new Date(ms).toISOString();
  }
  return String(value);
}

const LOCATIONS = {
  CW: { locationId: 'DSe5PdPEScZL8cbZTkKI', ghlToken: 'pit-34c1d79d-0bfa-4ddc-8349-11ce00ff9df5' },
  RANCES: { locationId: '1j1dHo8HEbZdElQUGFoC', ghlToken: 'pit-e8ac1488-cb01-484d-98f9-a4b2bcae4c92' }
};

const results = [];
for (let i = headerRowIndex + 1; i < rows.length; i++) {
  const rawRow = rows[i];
  const row = {};
  for (const [key, val] of Object.entries(rawRow)) {
    const columnName = headerMap[key];
    if (columnName) row[columnName] = val;
  }

  const customerUniqueId = row['Customer Unique ID'] || '';
  if (!customerUniqueId) continue;

  const leadSource = String(row['Lead Source'] || '').toUpperCase();
  const dealer = leadSource.includes('RANCES') ? 'RANCES' : 'CW';
  const loc = LOCATIONS[dealer];

  const digitsOnly = String(row['Mobile Phone'] || '').replace(/\D/g, '');
  const phone = digitsOnly ? ('+1' + digitsOnly.slice(-10)) : '';
  const email = String(row['Email'] || '').trim();
  const firstName = row['First Name'] || '';
  const lastName = row['Last Name'] || '';

  const ghlBody = { locationId: loc.locationId, tags: ['DealerCenter Sync'] };
  if (email) ghlBody.email = email;
  if (phone) ghlBody.phone = phone;
  if (firstName) ghlBody.firstName = firstName;
  if (lastName) ghlBody.lastName = lastName;
  const canSyncToGhl = Boolean(email || phone);

  results.push({
    json: {
      customerUniqueId,
      firstName,
      lastName,
      email,
      phone,
      customerStatus: row['Customer Status'] || '',
      customerStage: row['Customer Stage'] || '',
      leadSource: row['Lead Source'] || '',
      leadType: row['Lead Type'] || '',
      createdDate: excelDateToISO(row['Customer Created Date']),
      updatedDate: excelDateToISO(row['Last Updated Date']),
      assignedRep: row['Sales Rep'] || '',
      vehicleInterest: row['Interested Vehicle'] || '',
      vehicleSold: row['Sold Vehicle'] || '',
      nextAppointment: excelDateToISO(row['Next Appointment']),
      dealer,
      locationId: loc.locationId,
      ghlToken: loc.ghlToken,
      ghlBody,
      canSyncToGhl
    },
    pairedItem: { item: 0 }
  });
}

return results;
